import { useCallback, useEffect, useRef, useState } from 'react'
import { connect } from 'react-redux'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { Container, Button } from '../../../components'
import DynamicForm from '../../../components/DynamicForm'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { REGISTRATION_DATA } from '../../../constants/cookies'
import { AGENT_TYPE, checkIsCorporateAgent } from '../../../constants/appConstants'
import AuthActions from '../../../redux/auth/action'
import ErrorActions from '../../../redux/error/action'
import LoadingActions from '../../../redux/loading/action'
import { ERROR_LANG } from '../../../lang'
import { setToLocalStorage } from '../../../helpers/localstorage'
import { REGISTER_ILLUSTRATION } from '../../../images'
import { isIos } from '../../../helpers/utility'
import { webengageUserPhone, webengageUserName, webengageUserSignedUp, webengageUserEmail } from '../../../bridges/android'
import { webengageUserPhoneInIos, webengageUserNameInIos, webengageUserSignedUpInIos, webengageUserEmailInIos } from '../../../bridges/iOS'
import TermsAndConditionModal from './TermsAndConditionModal'
import { AGENT_TYPE_OPTIONS, REGISTER_FIELDS_BY_TYPE } from './constants'
import { RegisterWrapper } from './index.style'
import { gTagOnSignupFormSubmit } from './tagManager'

function Register (props) {
  const {
    loggedIn,
    history,
    validateAgentLoading,
    validateAgentError,
    validateAgentStatus,
    validateAgent,
    resetErrorRedux,
    resetLoadingRedux
  } = props

  const [agentType, setAgentType] = useState(AGENT_TYPE.INDIVIDUAL)
  const [isBtnDisable, setIsBtnDisable] = useState(true)

  const formRef = useRef(null)
  const isAgreeTermsRef = useRef(false)
  const formDataRef = useRef(null)

  useEffect(() => {
    if (loggedIn) {
      history.push('/dashboard')
    }
    resetErrorRedux(['VALIDATE_AGENT'])
    resetLoadingRedux(['VALIDATE_AGENT'])
  }, [history, loggedIn, resetErrorRedux, resetLoadingRedux])

  useEffect(() => {
    if (validateAgentError && validateAgentLoading === false) {
      NotificationManager.error(validateAgentStatus)
      resetErrorRedux(['VALIDATE_AGENT'])
      resetLoadingRedux(['VALIDATE_AGENT'])
    }
    if (validateAgentError === false && validateAgentLoading === false) {
      const body = {
        ...validateAgentStatus,
        ...formDataRef.current,
        isRegistration: true
      }
      setToLocalStorage(REGISTRATION_DATA, body)
      history.push({
        pathname: '/registration/verify',
        state: body
      })
      resetErrorRedux(['VALIDATE_AGENT'])
      resetLoadingRedux(['VALIDATE_AGENT'])
    }
  }, [history, validateAgentError, validateAgentLoading, validateAgentStatus, resetErrorRedux, resetLoadingRedux])

  const handleAgentTypeChange = (type) => {
    if (type === agentType) return
    // remounts the form (key={agentType}) so previous values/errors are cleared
    setAgentType(type)
    setIsBtnDisable(true)
  }

  const handleFormChange = useCallback(() => {
    setIsBtnDisable(!isAgreeTermsRef.current)
  }, [])

  const handleAgreeTerms = useCallback((isAgree) => {
    isAgreeTermsRef.current = isAgree
    setIsBtnDisable(!isAgreeTermsRef.current)
  }, [])

  const handleSubmit = () => {
    if (!isAgreeTermsRef.current) {
      NotificationManager.error(ERROR_LANG.disclaimerError)
      return
    }
    const values = formRef.current.validateFormValues()
    if (!values) return

    const isCorporateAgent = checkIsCorporateAgent(agentType)

    const body = isCorporateAgent
      ? {
        agent_type: AGENT_TYPE.CORPORATE,
        name: values.name,
        corporate_pic_name: values.corporate_pic_name,
        phone_no: values.phone_no,
        email: values.email,
        referral_code: values.referral_code?.trim()
      }
      : {
        agent_type: AGENT_TYPE.INDIVIDUAL,
        name: values.name,
        dob: values.dob,
        phone_no: values.phone_no,
        email: values.email,
        referral_code: values.referral_code?.trim()
      }

    formDataRef.current = body
    gTagOnSignupFormSubmit(values)
    validateAgent(body)

    if (isIos()) {
      webengageUserNameInIos(values.name)
      webengageUserPhoneInIos(values.phone_no)
      webengageUserEmailInIos(values.email)
      webengageUserSignedUpInIos()
    } else {
      webengageUserName(values.name)
      webengageUserPhone(values.phone_no)
      webengageUserEmail(values.email)
      webengageUserSignedUp()
    }
  }

  return (
    <Container title='daftar' loader={validateAgentLoading}>
      <RegisterWrapper>
        <div className='register-illustration'>
          <img src={REGISTER_ILLUSTRATION} alt='' />
        </div>
        <div className='register-heading'>
          <p className='register-title'>Daftar Menjadi Mitra</p>
          <p className='register-subtitle'>Ayo bergabung menjadi keluarga Mitra PasarPolis!</p>
        </div>
        <div className='agent-type-toggle'>
          {AGENT_TYPE_OPTIONS.map((option) => (
            <button
              key={option.value}
              type='button'
              data-testid={`agent-type-${option.value}`}
              className={`toggle-option ${agentType === option.value ? 'active' : ''}`}
              onClick={() => handleAgentTypeChange(option.value)}
            >
              {option.label}
            </button>
          ))}
        </div>
        <DynamicForm
          key={agentType}
          ref={formRef}
          form={REGISTER_FIELDS_BY_TYPE[agentType]}
          formName='registrationForm'
          className='registration-form'
          onChange={handleFormChange}
        />
        <TermsAndConditionModal
          onAgreeTermsNConditions={handleAgreeTerms}
        />
        <div className='register-submit'>
          <Button
            type='submit'
            id={isBtnDisable ? undefined : 'registration-submit'}
            disabled={isBtnDisable}
            onClick={handleSubmit}
            borderRadius='10px'
            backgroundColor={AgentColorPallette.primary}
            color={AgentColorPallette.darkCharcoal}
          >
            Selanjutnya
          </Button>
        </div>
        <NotificationContainer />
      </RegisterWrapper>
    </Container>
  )
}

export default connect(state => ({
  loggedIn: !!state.Auth.agent_token,
  validateAgentLoading: state.Loading.VALIDATE_AGENT,
  validateAgentError: state.Error.VALIDATE_AGENT,
  validateAgentStatus: state.Auth.validateAgentStatus
}), {
  validateAgent: AuthActions.validateAgent,
  resetLoadingRedux: LoadingActions.resetLoadingRedux,
  resetErrorRedux: ErrorActions.resetErrorRedux,
})(Register)
