import { Component } from 'react'
import { REGISTER_USER_TERMS } from '../../../../../constants/registerTermsConditions'
import Button from '../../../../../components/Button'
import CustomText from '../../../../../components/CustomText'
import { LANG_STRINGS } from '../../../../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { TermsContainerStyle, TermsOverflowHidden, TermsButtonStyle } from './index.style'

class RegisterTermsConditions extends Component {
  state = {
    isDisabled: true
  }

  componentDidMount () {
    const scrollDiv = document.getElementById('terms-body-content')
    const contentElement = document.getElementById('terms-content')
    const scrollHandler = () => {
      // this is the handler function run for scroll
      const scrollDivBoundingClientReact = scrollDiv.getBoundingClientRect()
      if (this.state.isDisabled && contentElement.getBoundingClientRect().bottom < scrollDivBoundingClientReact.bottom) {
        // once the button active then simple active the disable button
        // and remove the event listener
        this.setState({
          isDisabled: false
        })
        scrollDiv.removeEventListener('scroll', scrollHandler, true)
      }
    }
    scrollDiv.addEventListener('scroll', scrollHandler, true)
  }

  handleAgreeDisagree = (isAgree) => {
    // handle the agree
    this.props.onAgreeAndDisagree(isAgree)
  }

  renderSubcategoryTerms = (term, id) => {
    const { subCategories, type, listClass } = term
    return (
      <li key={`sub_cat_terms_${id}`}>
        {term.subCategoryTitle}
        {
          <ol className={listClass} type={type || 'a'}>
            {
              subCategories.map((item, subIndex) => (
                typeof item === 'object' ? this.renderTermsSection(item) : (
                  <li key={`subcategory-${id}-${subIndex}`}>{item}</li>
                )
              ))
            }
          </ol>
        }
        {
          term.bottom && (
            <CustomText
              size='11px'
              top='10px'
              color={AgentColorPallette.black}
              id={`bottom-content-${id}`}
            >
              {term.bottom}
            </CustomText>
          )
        }
      </li>
    )
  }

  renderTermsSection = (term) => {
    const { subCategories, type, listClass, index, subCategoryTitle, id } = term
    if (subCategoryTitle) {
      return this.renderSubcategoryTerms(term, id)
    }
    return (
      <TermsContainerStyle id='terms-content' key={`terms-content-${term.id}`}>
        <div className='terms-title'>{index ? `${index}. ` : ''}{term.title}</div>
        {term.subTitle1 && <div>{term.subTitle1}</div>}
        {term.subTitle2 && <div className='terms-subtitle-2'>{term.subTitle2}</div>}
        {
          <ol className={listClass} type={type || 'a'}>
            {
              subCategories.map((item, subIndex) => (
                typeof item === 'object' ? this.renderTermsSection(item) : (
                  <li key={`sub_cat_${id}_${subIndex}`}>{item}</li>
                )
              ))
            }
          </ol>
        }
        {
          term.bottom && (
            <CustomText
              size='11px'
              top='10px'
              color={AgentColorPallette.black}
              id={`bottom-content-${index}`}
              bottom='10px'
            >
              {term.bottom}
            </CustomText>
          )
        }
      </TermsContainerStyle>
    )
  }

  render () {
    return (
      <>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          className='terms-header-container'
          id='terms-header-container'
        >
          {LANG_STRINGS.termsAndConditionForPasarPolisPartner}
        </CustomText>
        <TermsOverflowHidden id='terms-body-content'>
          {
            REGISTER_USER_TERMS.map(term => this.renderTermsSection(term))
          }
        </TermsOverflowHidden>
        <TermsButtonStyle>
          <CustomText
            color={AgentColorPallette.black}
            size='10px'
            bottom='4px'
          >
            *{LANG_STRINGS.pleaseReadTheTermsToAgree}
          </CustomText>
          <Button
            variant='filled'
            disabled={this.state.isDisabled}
            onClick={() => this.handleAgreeDisagree(true)}
          >
            {LANG_STRINGS.agreeNew}
          </Button>
          <Button
            variant='filled'
            onClick={() => this.handleAgreeDisagree(false)}
          >
            {LANG_STRINGS.disagree}
          </Button>
        </TermsButtonStyle>
      </>
    )
  }
}

export default RegisterTermsConditions
